// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是各仓库阈值配置相对仓库根目录的路径。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 config/thresholds.json：配了就用自己的阈值，没配（或配置读不出来）
// 就回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	return thresholdFromFile(thresholdsPath(), warehouse)
}

// thresholdFromFile 从 path 读取仓库阈值。文件不存在、读不出来、内容不是
// JSON 对象、或其中没有这个仓库时，一律回退 DefaultLowStockThreshold。
func thresholdFromFile(path, warehouse string) int {
	data, err := os.ReadFile(path)
	if err != nil {
		return DefaultLowStockThreshold
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// thresholdsPath 定位仓库根目录下的 config/thresholds.json，使结果不依赖进程的
// 工作目录（go test 会把每个包的工作目录设成包目录）。
func thresholdsPath() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return thresholdsFile
	}
	return filepath.Join(filepath.Dir(file), "..", thresholdsFile)
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// 这些测试覆盖 issue-001 的新行为（阈值来自 config/thresholds.json）。
// 它们放在新文件里：inventory/stock_test.go 是冻结的验收基线，不许改。

// TestConfiguredWarehouseUsesConfiguredThreshold 断言仓库配在文件里时就用自己的阈值。
// 期望值直接从文件里读出来，这样换掉 config/thresholds.json 的内容也不会让测试变脆。
func TestConfiguredWarehouseUsesConfiguredThreshold(t *testing.T) {
	data, err := os.ReadFile(thresholdsPath())
	if err != nil {
		t.Skipf("没有配置文件可测：%v", err)
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		t.Skipf("配置不是 JSON 对象：%v", err)
	}
	if len(thresholds) == 0 {
		t.Skip("配置里没有仓库")
	}
	for warehouse, want := range thresholds {
		if got := LowStockThreshold(warehouse); got != want {
			t.Fatalf("LowStockThreshold(%q) = %d，期望配置值 %d", warehouse, got, want)
		}
	}
}

// TestWarehouseNotInConfigFallsBackToDefault 断言没配的仓库回退默认阈值。
func TestWarehouseNotInConfigFallsBackToDefault(t *testing.T) {
	const warehouse = "__not_configured_in_thresholds_json__"
	if got := LowStockThreshold(warehouse); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(%q) = %d，期望默认值 %d",
			warehouse, got, DefaultLowStockThreshold)
	}
}

// TestThresholdFromFileFallback 覆盖验收里点名的回退情形：
// 文件不存在、读不出来、内容不是 JSON 对象，一律回退。
func TestThresholdFromFileFallback(t *testing.T) {
	dir := t.TempDir()

	notJSON := filepath.Join(dir, "not-object.json")
	if err := os.WriteFile(notJSON, []byte(`["beijing", 12]`), 0o644); err != nil {
		t.Fatal(err)
	}
	invalid := filepath.Join(dir, "invalid.json")
	if err := os.WriteFile(invalid, []byte(`{`), 0o644); err != nil {
		t.Fatal(err)
	}
	unreadable := filepath.Join(dir, "unreadable.json")
	if err := os.WriteFile(unreadable, []byte(`{"beijing": 12}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(unreadable, 0o000); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(unreadable, 0o644) })

	configured := filepath.Join(dir, "configured.json")
	if err := os.WriteFile(configured, []byte(`{"beijing": 12}`), 0o644); err != nil {
		t.Fatal(err)
	}

	cases := []struct {
		name      string
		path      string
		warehouse string
		want      int
	}{
		{"文件不存在", filepath.Join(dir, "missing.json"), "beijing", DefaultLowStockThreshold},
		{"内容不是 JSON 对象", notJSON, "beijing", DefaultLowStockThreshold},
		{"内容不是合法 JSON", invalid, "beijing", DefaultLowStockThreshold},
		{"文件读不出来", unreadable, "beijing", DefaultLowStockThreshold},
		{"配了就用配置值", configured, "beijing", 12},
		{"没配就回退", configured, "chengdu", DefaultLowStockThreshold},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := thresholdFromFile(tc.path, tc.warehouse); got != tc.want {
				t.Fatalf("thresholdFromFile(%q, %q) = %d，期望 %d",
					tc.path, tc.warehouse, got, tc.want)
			}
		})
	}
}
